<?php require '../includes/functions.php';$u=require_role('citizen');verify_csrf();if($_SERVER['REQUEST_METHOD']!=='POST')redirect('citizen/dashboard.php');$id=(int)($_POST['grievance_id']??0);$rating=(int)($_POST['rating']??0);$comments=trim($_POST['comments']??'');if($rating<1||$rating>5){flash('Choose a rating from 1 to 5.');redirect('citizen/view.php?id='.$id);}$q=db()->prepare("INSERT INTO feedback(grievance_id,citizen_id,rating,comments) SELECT id,citizen_id,?,? FROM grievances WHERE id=? AND citizen_id=? AND status='Resolved'");try{$q->execute([$rating,$comments?:null,$id,$u['id']]);flash('Thank you for your feedback.');}catch(PDOException $e){flash('Feedback could not be recorded. It may already have been submitted.');}redirect('citizen/view.php?id='.$id);
